//! The Colossus fight's sound effects (generated by
//! `tools/make_colossus_sfx.py`): its wind-ups and slams, the clap, the
//! head's charge and gaze, the meteor storm and vents, and the player's
//! blows landing on it.

use quartz::*;

#[derive(Clone, Copy, Debug)]
pub enum Sfx { Windup, Slam, Clap, Charge, Beam, Meteor, Vent, Clang, Break }

pub fn play(c: &mut Canvas, sfx: Sfx) {
    let (bytes, vol): (&'static [u8], f32) = match sfx {
        Sfx::Windup => (include_bytes!("../../../../assets/colossus_windup.wav"), 0.45),
        Sfx::Slam => (include_bytes!("../../../../assets/colossus_slam.wav"), 0.85),
        Sfx::Clap => (include_bytes!("../../../../assets/colossus_clap.wav"), 0.8),
        Sfx::Charge => (include_bytes!("../../../../assets/colossus_charge.wav"), 0.5),
        Sfx::Beam => (include_bytes!("../../../../assets/colossus_beam.wav"), 0.6),
        Sfx::Meteor => (include_bytes!("../../../../assets/colossus_meteor.wav"), 0.55),
        Sfx::Vent => (include_bytes!("../../../../assets/colossus_vent.wav"), 0.5),
        Sfx::Clang => (include_bytes!("../../../../assets/colossus_clang.wav"), 0.6),
        Sfx::Break => (include_bytes!("../../../../assets/colossus_break.wav"), 0.9),
    };
    // Headless check: `COLOSSUS_SFX_LOG=1` prints each sound as it plays.
    if std::env::var("COLOSSUS_SFX_LOG").is_ok() {
        eprintln!("COLOSSUS_SFX {:?}", sfx);
    }
    let v = crate::scenes::game::helpers::sfx_vol(c, vol);
    c.play_sound_bytes_with(bytes, SoundOptions::new().volume(v));
}

/// One part's frame, reduced to what its sounds need. Each part's last
/// stage is kept on the canvas, and a sound plays on the frame a stage BEGINS
/// (a wind-up, a strike, a shot), never every frame it lasts.
pub fn part_frame(c: &mut Canvas, id: &str, telegraph: bool, attack: bool, beam_on: bool,
                  clap: bool, storm: bool, vent: bool) {
    let stage = if attack { 2 } else if telegraph { 1 } else { 0 };
    let key = format!("col_sfx_{id}");
    let last = match c.get_var(&key) { Some(Value::I32(v)) => v, _ => 0 };
    let flag = |c: &Canvas, k: &str| matches!(c.get_var(k), Some(Value::Bool(true)));
    c.set_var(&key, stage);
    let head = id == "head";
    if stage == 1 && last == 0 {
        play(c, if head { Sfx::Charge } else { Sfx::Windup });
    }
    if stage == 2 && last != 2 && !head {
        play(c, Sfx::Slam);
    }
    let beam_key = format!("col_sfx_{id}_beam");
    if head && beam_on && !flag(c, &beam_key) {
        play(c, Sfx::Beam);
    }
    c.set_var(&beam_key, head && beam_on);
    if clap { play(c, Sfx::Clap); }
    for (on, name, sfx) in [(storm, "storm", Sfx::Meteor), (vent, "vent", Sfx::Vent)] {
        let k = format!("col_sfx_{id}_{name}");
        if on && !flag(c, &k) { play(c, sfx); }
        c.set_var(&k, on);
    }
}
